#!/usr/bin/env python3
"""developer-portal.html: replace the three small screenshots (the dp-shots grid) with
one full-width shot of the portal's Try it tab. The screenshot is built into this
script: --apply writes it to docs/screenshots/portal-try-it-full.png.

  --site PATH   the site folder (default ~/GetHub/orchestrator/docs)

Dry run by default (prints the block it removes); --apply writes the page
(developer-portal.html.bak beside it).
"""
import base64, pathlib, re, shutil, sys

PNG_B64 = ""

APPLY = "--apply" in sys.argv
SITE = pathlib.Path(sys.argv[sys.argv.index("--site") + 1] if "--site" in sys.argv
                    else "~/GetHub/orchestrator/docs").expanduser()
page = SITE / "developer-portal.html"
s = page.read_text(encoding="utf-8")

if "portal-try-it-full.png" in s:
    sys.exit("already replaced - nothing to do")
IMG = SITE / "screenshots" / "portal-try-it-full.png"
if s.count('<div class="dp-shots">') != 1:
    sys.exit('expected exactly one <div class="dp-shots">')

start = s.index('<div class="dp-shots">')
start = s.rfind("\n", 0, start) + 1                      # whole line, with its indent
ind = re.match(r"[ \t]*", s[start:]).group(0)
# the three figures end at the third </figure>; the next </div> closes dp-shots
figs = [m.end() for m in re.finditer(r"</figure>", s[start:])][:3]
if len(figs) != 3:
    sys.exit("did not find three </figure> after dp-shots")
after3 = start + figs[2]
end = s.index("</div>", after3) + len("</div>")
if s[after3:end - len("</div>")].strip():
    sys.exit("unexpected markup between the third </figure> and </div> - send me lines 260-312")
end = s.index("\n", end) + 1 if "\n" in s[end:end + 2] else end

new = (f'{ind}<div class="dp-shot-wide" style="max-width:1200px;margin:0 auto;">\n'
       f'{ind}  <img src="/screenshots/portal-try-it-full.png" '
       f'alt="Magertron Developer Portal - an approved tool with a green You can call this tool '
       f'banner, its arguments, the equivalent curl, and a live call run against the gateway '
       f'returning HTTP 200" loading="lazy" '
       f'style="display:block;width:100%;height:auto;border-radius:12px;'
       f'border:1px solid var(--border);box-shadow:0 20px 50px rgba(0,0,0,.35);">\n'
       f'{ind}</div>\n')

print("--- removed ---\n" + s[start:end] + "--- added ---\n" + new)
s = s[:start] + new + s[end:]
if APPLY:
    IMG.parent.mkdir(exist_ok=True)
    IMG.write_bytes(base64.b64decode(PNG_B64))
    print(f"wrote {IMG}")
    shutil.copy2(page, str(page) + ".bak")
    page.write_text(s, encoding="utf-8")
    print("applied (developer-portal.html.bak beside it)")
else:
    print("dry run - re-run with --apply to write")

